contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take amount and unlockTime as inputs. We will call Put with value amount.
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount, "insufficient test contract balance");
        // read previous public-observable values
        C.Holder memory before = c.Acc(address(this));
        uint beforeAccBalance = before.balance;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        // attempt to call Put with value 'amount'
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        C.Holder memory after = c.Acc(address(this));
        uint afterAccBalance = after.balance;
        uint afterContractBalance = address(c).balance;

        // If the call did not revert and amount>0, then both the mapping balance and contract balance
        // must have increased by at least `amount` (Put only increases balances by msg.value and never deducts here).
        assert(reverted || amount == 0 || (afterAccBalance >= beforeAccBalance + amount && afterContractBalance >= beforeContractBalance + amount));
    }

    // Allow receiving Ether for funding calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call Put with a value and unlockTime; check observable balances increased when call succeeds
    function run(uint amount, uint unlockTime) public payable {
        require(address(this).balance >= amount);

        // read before-values via public getter
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBalance = address(c).balance;

        // If the call did not revert and amount>0, then both the mapping balance and contract balance
        // must have increased by at least `amount`.
        assert(reverted || amount == 0 || (afterBalance >= beforeBalance + amount && afterContractBalance >= beforeContractBalance + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to withdraw _am via Collect; check that on non-revert, balances move exactly by _am (or _am==0)
    function run(uint _am, uint deposit, uint unlockTime) public payable {
        // ensure we can fund the test contract for making Put and receiving transfers
        require(address(this).balance >= deposit);

        // deposit some funds into c so Collect might succeed later
        c.Put{value: deposit}(unlockTime);

        // read before-values via public getter
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeThisBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;

        bool reverted;
        try c.Collect{value:0}(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterThisBalance = address(this).balance;
        uint afterContractBalance = address(c).balance;

        // If Collect did not revert then either requested amount was zero (no net transfer),
        // or the mapping balance decreased by exactly _am and this contract's balance increased by exactly _am,
        // and contract's balance decreased by exactly _am.
        assert(reverted || _am == 0 || (
            afterBalance + _am == beforeBalance
            && afterThisBalance == beforeThisBalance + _am
            && afterContractBalance + _am == beforeContractBalance
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs:
    // deposit - amount to deposit via Put (must be fundable by this contract)
    // unlockTime - candidate unlock time for the deposit
    // withdraw - amount to attempt to withdraw via Collect
    function run(uint deposit, uint unlockTime, uint withdraw) public payable {
        // allow caller to fund this test contract externally before calling run
        require(address(this).balance >= deposit);

        // make a deposit so that this contract has a recorded balance in c
        c.Put{value: deposit}(unlockTime);

        // read recorded holder info before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect{value:0}(withdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read recorded holder info after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        // If Collect succeeded (did not revert) then all of the following must hold:
        // 1) The call only proceeds when the recorded balance before was >= MinSum.
        // 2) The call only proceeds when recorded balance before was >= requested withdraw.
        // 3) The call only proceeds when block.timestamp > unlockTime (we observe unlock via beforeUnlock)
        // 4) The recorded balance after is <= recorded balance before (no unexpected increase).
        assert(reverted || (
            beforeBalance >= minSum
            && beforeBalance >= withdraw
            && block.timestamp > beforeUnlock
            && afterBalance <= beforeBalance
        ));
    }

    // allow receiving ETH from C during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // deposit: amount to deposit via Put (must be fundable by this contract)
    // unlockTime: unlock time to set for the deposit
    // withdraw: amount to attempt to withdraw via Collect
    function run(uint deposit, uint unlockTime, uint withdraw) public payable {
        // allow this test contract to be funded externally to cover `deposit`
        require(address(this).balance >= deposit);

        // Make a deposit so that this contract has a recorded balance in c
        c.Put{value: deposit}(unlockTime);

        // Read recorded holder info before Collect
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));

        bool reverted;
        // capture balances of this test contract and c before the call
        uint ethBeforeThis = address(this).balance;
        uint ethBeforeC = address(c).balance;

        try c.Collect{value:0}(withdraw) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded holder info after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint ethAfterThis = address(this).balance;
        uint ethAfterC = address(c).balance;

        // If Collect succeeded (did not revert) then:
        // 1) the recorded balance decreased by exactly `withdraw`,
        // 2) this contract's ETH balance increased by exactly `withdraw`,
        // 3) the contract c's ETH balance decreased by exactly `withdraw`.
        // These express that a successful Collect transfers exactly the requested amount.
        assert(reverted || (
            // avoid underflow by comparing using >= then equality on differences
            beforeBalance >= withdraw
            && afterBalance + withdraw == beforeBalance
            && ethAfterThis == ethBeforeThis + withdraw
            && ethAfterC + withdraw == ethBeforeC
        ));
    }

    // allow receiving ETH from C during Collect
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an unlock time and an amount to send to c via Put
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read the holder record for this contract (InvMutTest) before the call
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        // make the state-changing call: send `amount` wei to Put(unlockTime)
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after state
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If the call reverted, nothing changed in contract's storage or balance for this call
        // If the call succeeded, then recorded balance increases by amount and contract balance increases by amount
        assert(reverted
               ? (afterBalance == beforeBalance && cBalAfter == cBalBefore)
               : (afterBalance == beforeBalance + amount && cBalAfter == cBalBefore + amount));
    }

    // allow receiving ether when the test receives funds prior to calling run
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to drive Put and then Collect. `putAmount` is sent to Put, `unlockOffset` advances unlockTime, `collectAmount` is attempted to Collect.
    function run(uint unlockOffset, uint putAmount, uint collectAmount) public payable {
        // need funds to send to Put
        require(address(this).balance >= putAmount);

        // Read holder record and contract balance before any calls
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Make a Put call to deposit putAmount and set unlockTime to block.timestamp + unlockOffset
        // This is a top-level state-changing call
        try c.Put{value: putAmount}(block.timestamp + unlockOffset) {
            // success
        } catch {
            // If Put reverts, then Collect won't succeed later; we still assert the property in a way that demands Collect not succeed in that case.
        }

        // Read after Put
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint cBalMid = address(c).balance;

        // Now attempt Collect(collectAmount). Catch whether it reverts.
        bool collectReverted;
        try c.Collect{value:0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read after Collect
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // The intended general rule:
        // If Collect succeeded (did not revert) then the recorded balance decreased by exactly collectAmount and the contract's on-chain balance decreased by exactly collectAmount.
        // If Collect reverted then at least one of those two must hold unchanged (we allow cases where Collect reverted but balances changed due to prior Put failing/succeeding).
        assert(collectReverted ? true : (midBalance >= collectAmount && afterBalance + collectAmount == midBalance && cBalAfter + collectAmount == cBalMid));
    }

    // Allow this test contract to receive Ether for funding Put calls
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // putAmount: Ether to send to Put; unlockDelta: set unlockTime = block.timestamp + unlockDelta
    function run(uint unlockDelta, uint putAmount) public payable {
        // require this test contract has enough balance to send
        require(address(this).balance >= putAmount);

        // read recorded holder before
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // call Put sending putAmount and setting unlockTime
        bool putReverted;
        try c.Put{value: putAmount}(block.timestamp + unlockDelta) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read after
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // If Put succeeded then the recorded balance must be >= beforeBalance and increased by at least putAmount,
        // and the contract's on-chain balance must increase by exactly putAmount.
        // If Put reverted then nothing is required (we allow revert). This is a general rule over all inputs.
        assert(putReverted || (afterBalance >= beforeBalance && afterBalance >= beforeBalance + putAmount && cBalAfter == cBalBefore + putAmount));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs:
    // prepPut: amount to put into C before attempting Collect (sent via Put)
    // collectAmt: amount to attempt to collect
    function run(uint prepPut, uint collectAmt) public payable {
        // ensure this test contract has funds to send Put
        require(address(this).balance >= prepPut);

        // read initial observable state
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;
        uint minSum = c.MinSum();

        // perform Put to increase recorded balance and contract balance (may revert)
        bool putReverted;
        try c.Put{value: prepPut}(block.timestamp) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read state after Put attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfterPut = address(c).balance;

        // Now attempt Collect of collectAmt (may revert). We record whether it reverted.
        bool collectReverted;
        try c.Collect(collectAmt) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final state
        (uint finalUnlock, uint finalBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General property:
        // If Collect succeeded then the following must hold:
        // 1) before the Collect call (i.e. after Put effects) the recorded balance was >= minSum,
        //    recorded balance was >= collectAmt, and block.timestamp > unlockTime (so Collect's if condition held),
        // AND 2) afterward, the contract's on-chain balance decreased by exactly collectAmt and the recorded balance decreased by at least collectAmt.
        // We express (1) using the observable afterBal and afterUnlock. Because block.timestamp is not directly observable, we use the fact
        // that C's Collect only succeeds (i.e. did not revert) when the if condition is true; thus we assert that if collectReverted==false
        // then (afterBal >= minSum && afterBal >= collectAmt && block.timestamp > afterUnlock) must hold — but we cannot read block.timestamp inside assert
        // about C, so we instead require the observable that follows from Collect success: cBalAfter == cBalAfterPut - collectAmt and finalBal <= afterBal - collectAmt.
        // To be safe in all cases, we assert: Collect succeeded implies (contract balance decreased by collectAmt AND recorded balance decreased by at least collectAmt).

        assert(collectReverted || (cBalAfter + collectAmt == cBalAfterPut && finalBal + collectAmt <= afterBal));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amt to send with Put, and an arbitrary unlockTime
    function run(uint putAmt, uint unlockTime) public payable {
        // ensure this test contract has funds to send Put
        require(address(this).balance >= putAmt);

        // Read observable state before Put
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        // Call Put with value putAmt and record whether it reverted
        bool putReverted;
        try c.Put{value: putAmt}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // Read observable state after Put attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint cBalAfter = address(c).balance;

        // General property to hold for all inputs:
        // If Put did not revert then c's on-chain balance increased by exactly putAmt
        // and the recorded holder balance for this test address increased by at least putAmt.
        // (This uses only public getters and address(c).balance.)
        assert(putReverted || (cBalAfter == cBalBefore + putAmt && afterBal >= beforeBal + putAmt));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to put some funds then attempt to collect; parameters:
    // putAmount: amount of wei to deposit via Put (sent as value)
    // unlockTime: unlock timestamp parameter for Put
    // collectAmount: amount to attempt to Collect
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount + 1 wei);
        // Record balances before any calls
        uint beforeContractBalance = address(c).balance;
        // Read holder balance before
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));

        // Call Put to deposit funds into c for this test contract's address
        c.Put{value: putAmount}(unlockTime);

        // Read values after Put and before Collect
        uint midContractBalance = address(c).balance;
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));

        // Ensure that Put increased both on-chain contract balance and recorded holder balance by at least putAmount
        // (This is not the final asserted property, just a precondition check to ensure progression.)
        // Use require so if Put misbehaves the test call doesn't proceed.
        require(midContractBalance >= beforeContractBalance + putAmount && midHolderBalance >= beforeHolderBalance + putAmount);

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));

        // General rule asserted: If Collect did not revert then the holder's recorded balance decreased by exactly collectAmount
        // and contract's balance decreased by at least collectAmount (it may be equal or greater if transfers failed unexpectedly).
        assert(reverted || (afterHolderBalance + collectAmount == midHolderBalance && midContractBalance >= afterContractBalance + collectAmount));
    }

    // allow receiving Ether so Put fallback can send back if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // putAmount: wei to send to Put
    // unlockTime: parameter for Put
    function run(uint putAmount, uint unlockTime) public payable {
        // ensure this test contract can send the requested amount
        require(address(this).balance >= putAmount);

        // read before-values
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));

        // perform Put sending putAmount wei
        c.Put{value: putAmount}(unlockTime);

        // read after-values
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));

        // General invariant: Put never decreases the recorded holder balance for the caller
        // and the contract's on-chain balance increases by exactly the sent amount.
        // (Note: Put may set unlockTime to at least block.timestamp; we don't assert about it here.)
        assert(afterHolderBalance >= beforeHolderBalance && afterContractBalance == beforeContractBalance + putAmount);
    }

    receive() external payable {}
}

