    // We will attempt a Put to fund this contract's holder entry in c, then try Collect.
    // Parameters:
    // - putAmount: amount of wei to send in Put (can be 0)
    // - unlockTime: passed to Put (uint)
    // - collectAmount: amount to request in Collect
    // Note: address(this) is the caller as required by the problem statement.
    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient balance for Put");

        // Record balances before any calls
        uint cBalanceBefore = address(c).balance;
        (uint accUnlockBefore, uint accBalanceBefore) = c.Acc(address(this));

        // Call Put to deposit putAmount into c for this test contract's holder
        if (putAmount > 0) {
            c.Put{value: putAmount}(unlockTime);
        } else {
            // still call Put with 0 to set unlockTime possibly
            c.Put{value: 0}(unlockTime);
        }

        // Observe after Put
        uint cBalanceAfterPut = address(c).balance;
        (uint accUnlockAfterPut, uint accBalanceAfterPut) = c.Acc(address(this));

        // Now attempt Collect for collectAmount and record whether it reverted
        bool reverted;
        // We must ensure we have some gas and don't rely on msg.value here.
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after Collect
        uint cBalanceAfterCollect = address(c).balance;
        (uint accUnlockAfterCollect, uint accBalanceAfterCollect) = c.Acc(address(this));

        // General rule to assert:
        // If Collect succeeded (not reverted) then the following must hold:
        //  - prior to Collect, the holder balance was >= MinSum and >= collectAmount
        //  - and block.timestamp was > unlockTime (we can only observe unlockTime stored)
        //  - after Collect, the contract's reported holder balance decreased by exactly collectAmount
        //  - and address(c).balance decreased by exactly collectAmount
        // If Collect reverted, then at least one of the preconditions (balance>=MinSum, balance>=collectAmount, block.timestamp>unlockTime)
        // must have been false (we approximate by checking that either holder balance before collect < collectAmount or holder balance before collect < c.MinSum() or the unlockTime was >= current block time).

        // Read public MinSum (callable view)
        uint minSum = c.MinSum();

        // Determine holder state immediately before Collect: that is accBalanceAfterPut and accUnlockAfterPut
        uint holderBalBeforeCollect = accBalanceAfterPut;
        uint holderUnlockBeforeCollect = accUnlockAfterPut;

        // Build the assertion: (reverted => one of preconditions false) AND (not reverted => balances decreased exactly)
        bool preconds_hold = (holderBalBeforeCollect >= minSum) && (holderBalBeforeCollect >= collectAmount) && (block.timestamp > holderUnlockBeforeCollect);

        bool balances_decreased_exact = (accBalanceAfterCollect + collectAmount == holderBalBeforeCollect) && (cBalanceAfterPut == cBalanceAfterCollect + collectAmount);

        assert( (reverted && !preconds_hold) || (!reverted && preconds_hold && balances_decreased_exact) );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

