        // depositAmount must be >= MinSum to allow Collect to possibly succeed later
        uint min = c.MinSum();
        require(depositAmount >= min, "deposit must be >= MinSum");
        // make an unlockTime in the past so Collect precondition (block.timestamp > unlockTime) can hold
        // we choose unlockTime = block.timestamp - pastUnlockOffset (if pastUnlockOffset==0 it's current time -> not past), so require >0
