        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After Put, read Acc and contract balance
        uint cBal_afterPut = address(c).balance;
        (uint unlock_afterPut, uint accBal_afterPut) = c.Acc(address(this));

        // Now attempt Collect of collectAmount. We catch whether it reverted.
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        uint cBal_afterCollect = address(c).balance;
        (uint unlock_afterCollect, uint accBal_afterCollect) = c.Acc(address(this));

        // General rule: if Collect succeeded (did not revert) then
        //  - the holder's stored balance decreased by exactly collectAmount
        //  - the contract's balance decreased by at least collectAmount
        // Note: we allow that Put might have reverted; in that case Collect likely reverts, so the assertion only claims the above when collect succeeded.
        assert(collectReverted || (accBal_afterCollect + collectAmount == accBal_afterPut && cBal_afterPut >= cBal_afterCollect && cBal_afterPut - cBal_afterCollect >= collectAmount));
    }

