        assert(
            (collectReverted && afterBalance == beforeBalance && afterAddrBalance == beforeAddrBalance)
            || (
                !collectReverted
                && afterBalance <= beforeBalance
                && beforeAddrBalance >= afterAddrBalance
                && (beforeBalance - afterBalance) == (beforeAddrBalance - afterAddrBalance)
                && (beforeBalance - afterBalance) <= beforeBalance
            )
        );
    }

    // allow receiving Ether if the C contract sends Ether to this test contract during Collect
    receive() external payable {}
}

