    function run(uint putAmount, uint unlockTime, uint collectAmount) public payable {
        // we will send Ether to c on Put; ensure this contract has enough balance to forward
        require(address(this).balance >= putAmount);

        // Observe initial recorded balance for this contract's address (as holder)
        (, uint beforeBal) = _holderOf(address(this));
        uint beforeAddrBal = address(c).balance;

        // Call Put to deposit funds and set unlockTime
        c.Put{value: putAmount}(unlockTime);

        // Observe intermediate recorded balance
        (, uint midBal) = _holderOf(address(this));
        uint midAddrBal = address(c).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe final recorded balance and contract balance
        (, uint afterBal) = _holderOf(address(this));
        uint afterAddrBal = address(c).balance;

        // If Collect did not revert then the recorded holder balance must have decreased by collectAmount
        // and the contract's ether balance must have decreased by exactly collectAmount as well.
        // Otherwise (if reverted) balances must be unchanged from mid-call to after-call.
        assert(
            (!reverted && midBal >= collectAmount && afterBal + collectAmount == midBal && midAddrBal >= collectAmount && afterAddrBal + collectAmount == midAddrBal)
            || (reverted && afterBal == midBal && afterAddrBal == midAddrBal)
        );
    }

    // helper to call the public mapping getter Acc(address) which returns Holder struct members
    function _holderOf(address a) internal view returns (uint unlockTime, uint balance) {
        // Acc is public so Solidity generates a getter with signature Acc(address) returns (uint unlockTime, uint balance)
        return c.Acc(a);
    }

    // fallback to accept Ether when needed
    receive() external payable {}
}

